settings._cssCustom:
#brxe-5d8fba { position: relative; padding-bottom: 72px; }
#brxe-5d8fba .splide__arrows { position: static; }
#brxe-5d8fba .splide__arrow { position: absolute; top: auto; bottom: 0; transform: none; width: 48px; height: 48px;
  border: 1.5px solid #f2f3f5; border-radius: 999px; background: transparent; opacity: 1; cursor: pointer;
  display: flex; align-items: center; justify-content: center; padding: 0; }
#brxe-5d8fba .splide__arrow--prev { left: 0; right: auto; opacity: .2; }
#brxe-5d8fba .splide__arrow--prev:hover:not(:disabled) { opacity: 1; }
#brxe-5d8fba .splide__arrow--next { left: 80px; right: auto; }
#brxe-5d8fba .splide__arrow svg { width: 14px; height: 14px; fill: #f2f3f5; transform: none; }
#brxe-5d8fba .splide__arrow--prev svg { transform: scaleX(-1); }
@media (max-width: 991px) {
  #brxe-5d8fba { padding-bottom: 52px; }
  #brxe-5d8fba .splide__arrow { width: 36px; height: 36px; }
  #brxe-5d8fba .splide__arrow--next { left: 60px; }
}
